#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Collections.Generic;using NUnit.Framework;using UnityEngine;using SporeGobbo.Geometry;using SporeGobbo.CampCandidate;using SporeGobbo.Safety;
public sealed class Stage64BLayoutTests
{
 static AuthoredCamp Layout=>SettlementCampLayout.Shared;
 static Point2 Fire=>Layout.Marker("fire").Interaction;
 static RegionTerrainState Terrain(bool roots=false,bool ordinary=false){var t=new RegionTerrainState("owned-layout-proof",192,192,Layout);var cells=new List<DualTile>();for(int y=0;y<192;y++)for(int x=0;x<192;x++){var k=Layout.Category(x,y);if(roots&&k==CampCell.FirstBuddy||ordinary&&(k==CampCell.Expansion||k==CampCell.Residential))cells.Add(new DualTile(x,y));}if(cells.Count>0)Assert.That(t.Commit(cells,0,c=>true),Is.EqualTo(cells.Count));return t;}
 static SporeSaveSlotData Old(bool root=false,bool bedrooms=false){var d=SporeSaveSlotData.CreateNew(3,"Owned old-layout contract","CampScene");var s=CampRegionSnapshot.Pristine();s.layoutId=LegacyCamp61CLayout.LayoutId;var cuts=new SortedSet<int>();if(root)foreach(var p in SettlementCampLayout.RootCells())cuts.Add(p.Y*192+p.X);if(bedrooms)for(int y=0;y<192;y++)for(int x=0;x<192;x++)if(LegacyCamp61CLayout.Shared.Category(x,y)==CampCell.Residential)cuts.Add(y*192+x);s.rootOpened=root;s.excavatedCells=cuts.ToArray();s.terrainRevision=cuts.Count==0?0:1;if(bedrooms){s.establishedBeds=Enumerable.Range(1,10).ToArray();d.campTerrainState.residentialSlotsEstablished=10;}d.campTerrainState.regionSnapshot=s;return d;}
 [Test]public void ExactAcceptedGeometryAndStableIdentities(){Assert.That(LegacyCamp61CLayout.Shared.Fingerprint(),Is.EqualTo(CampLayoutCompatibility.Accepted61CFingerprint));Assert.That(Layout.Capacity,Is.EqualTo(10));Assert.That(Layout.Fingerprint(),Is.EqualTo(SettlementCampLayout.Create().Fingerprint()));foreach(var old in LegacyCamp61CLayout.Shared.Bedrooms){var next=Layout.Bedrooms.Single(r=>r.Id==old.Id);Assert.That(next.FirstSlot,Is.EqualTo(old.FirstSlot));for(int i=0;i<old.Beds.Count;i++)Assert.That(next.Beds[i],Is.EqualTo(old.Beds[i]+new Point2(-2,-2)));}}
 [Test]public void EveryRealStationAndAllBedroomEntrancesHaveThreeCellAccess(){var t=Terrain();foreach(string id in new[]{"arrival.first","squad","bones","run.departure","shop.reserved",SettlementCampLayout.RootId})Assert.That(t.Route(Fire,Layout.Marker(id).Interaction,3),Is.Not.Empty,id);foreach(var room in Layout.Bedrooms)Assert.That(t.Route(Fire,room.Entrance,3),Is.Not.Empty,room.Id);Assert.That(t.Route(Layout.Marker("bones").Interaction,Layout.Marker("run.departure").Interaction,3),Is.Not.Empty);}
 [Test]public void ClosedRootCannotBeBypassedEvenByCompleteOrdinaryExcavation(){var t=Terrain(false,true);Assert.That(t.Route(Fire,CampFightPitLayout.Center,1),Is.Empty);Assert.That(t.Route(Fire,new Point2(129.5,95.5),1),Is.Empty);}
 [Test]public void OpenRootConnectsPitAndContinuousLargeSpectatorLoop(){var t=Terrain(true);Assert.That(t.Route(Fire,CampFightPitLayout.Entry,3),Is.Not.Empty);Assert.That(t.Route(Fire,CampFightPitLayout.Center,3),Is.Not.Empty);Point2 prior=CampFightPitLayout.Spectator(0);for(int i=1;i<=96;i++){var next=CampFightPitLayout.Spectator(i*Math.PI*2/96);Assert.That(t.Fits(next,3),Is.True,"spectator "+i);Assert.That(t.Route(prior,next,3),Is.Not.Empty,"loop "+i);prior=next;}}
 [Test]public void PermanentStripPreventsDirectBedroomPitCrossing(){for(int y=65;y<=96;y++)for(int x=122;x<=124;x++)Assert.That(Layout.Category(x,y),Is.EqualTo(CampCell.Permanent),x+","+y);}
 [Test]public void AllTenBedsHaveRealConstructionFootprintsAndReturnRoutes(){var catalog=SettlementCampLayout.Catalog(Layout);var t=Terrain();for(int id=1;id<=10;id++){var slot=catalog.GetSlot(id);var cells=slot.ExcavationFootprint.Select(p=>new DualTile(p.x,p.y)).ToArray();t.Commit(cells,t.Revision,c=>Layout.Category(c.X,c.Y)==CampCell.Residential);var rest=new Point2(slot.RestCell.x+.5,slot.RestCell.y+.5);Assert.That(t.Fits(rest,3),Is.True,"bed "+id);Assert.That(t.Route(rest,Fire,3),Is.Not.Empty,"return "+id);}}
 [Test]public void StationPermanentBackingsAndOriginalRootMaskRemainExact(){foreach(var m in LegacyCamp61CLayout.Shared.Markers.Where(m=>m.Id!="fight.reserved"&&m.Id!="arrival.first"&&m.Id!=SettlementCampLayout.RootId))for(int y=(int)m.Anchor.Y-4;y<=(int)m.Anchor.Y+3;y++)for(int x=(int)m.Anchor.X-4;x<=(int)m.Anchor.X+4;x++)if(LegacyCamp61CLayout.Shared.Category(x,y)==CampCell.Permanent)Assert.That(Layout.Category(x,y),Is.EqualTo(CampCell.Permanent),m.Id);Assert.That(SettlementCampLayout.RootCells().All(p=>Layout.Category(p.X,p.Y)==CampCell.FirstBuddy),Is.True);}
 [TestCase(false,false)][TestCase(true,false)][TestCase(false,true)][TestCase(true,true)]public void DetachedCompatibilityPreservesProgressAndCanonicalCampaign(bool roots,bool beds){var original=Old(roots,beds);string bytes=JsonUtility.ToJson(original);var next=CampLayoutCompatibility.Prepare(original,true);Assert.That(JsonUtility.ToJson(original),Is.EqualTo(bytes));Assert.That(next,Is.Not.SameAs(original));Assert.That(next.leader.uniqueId,Is.EqualTo(original.leader.uniqueId));Assert.That(next.campTerrainState.regionSnapshot.rootOpened,Is.EqualTo(roots));Assert.That(next.campTerrainState.regionSnapshot.establishedBeds,Is.EqualTo(original.campTerrainState.regionSnapshot.establishedBeds));CampaignSnapshotValidator.Validate(next);Assert.That(CampLayoutCompatibility.Prepare(next,true),Is.SameAs(next));var region=next.campTerrainState.regionSnapshot;next.campTerrainState.regionSnapshot=original.campTerrainState.regionSnapshot;Assert.That(JsonUtility.ToJson(next),Is.EqualTo(bytes));next.campTerrainState.regionSnapshot=region;}
 [Test]public void ExistingAuthoredFloorNeverBecomesClosedOnCompatibilityRead(){var next=CampLayoutCompatibility.Prepare(Old(),true);var world=next.campTerrainState.regionSnapshot.RestoreTerrain().World;for(int y=0;y<192;y++)for(int x=0;x<192;x++)if(LegacyCamp61CLayout.Shared.Category(x,y)==CampCell.Open)Assert.That(world.IsSolid(x,y),Is.False,x+","+y);}
 [Test]public void InvalidProtectedOldEditsFailBeforeAdaptation(){var d=Old();d.campTerrainState.regionSnapshot.excavatedCells=new[]{0};d.campTerrainState.regionSnapshot.terrainRevision=1;Assert.Throws<InvalidDataException>(()=>CampLayoutCompatibility.Prepare(d,true));}
 [Test]public void NormalProfileCannotSilentlyAdaptOldV1Campaign(){if(V1RuntimeProfile.StorageProfile!="normal")Assert.Ignore("normal-profile process contract");Assert.Throws<NotSupportedException>(()=>CampLayoutCompatibility.Prepare(Old(),false));}
 [Test]public void UnknownLayoutRemainsRejected(){var d=Old();d.campTerrainState.regionSnapshot.layoutId="unknown-owned-layout";Assert.That(CampLayoutCompatibility.Prepare(d,true),Is.SameAs(d));Assert.Throws<InvalidDataException>(()=>CampaignSnapshotValidator.Validate(d));}
 [Test]public void OldAuthenticatedFixtureReadThenAtomicCommitKeepsExactBackup(){var data=Old(true,true);string payload=JsonUtility.ToJson(data);var envelope=new DevelopmentCampaignSnapshot{format="SporeGobbo.DevelopmentCampaign",version=10,campaignId="development-layout-owned",generation=7,payload=payload,sha256=CampaignSnapshotStorage.Hash(payload)};string old=JsonUtility.ToJson(envelope);DevelopmentCampaignSnapshot.Decode(old,3,out var adapted);string next=DevelopmentCampaignSnapshot.Encode(adapted,envelope.campaignId,8);string path=Persistence.ExperimentPath("Stage64BLayout",Guid.NewGuid().ToString("N"),"slot.json");Action<string> valid=s=>DevelopmentCampaignSnapshot.Decode(s,3,out _);CampaignSnapshotStorage.Commit(path,old,valid);CampaignSnapshotStorage.Commit(path,next,valid);Assert.That(CampaignSnapshotStorage.Read(path+".bak"),Is.EqualTo(old));Assert.Throws<IOException>(()=>CampaignSnapshotStorage.Commit(path,next,valid,at=>{if(at=="flushed")throw new IOException("owned interruption");}));Assert.That(CampaignSnapshotStorage.Read(path),Is.EqualTo(next));}
}
#endif
